import React from 'react';
import { useNavigate } from 'react-router-dom';
import { MapPin, Maximize2, Bed, Bath, Heart } from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';

const PropertyCard = ({ property }) => {
  const navigate = useNavigate();

  const formatPrice = (price, type) => {
    if (type === 'rent') {
      return `₹${price.toLocaleString('en-IN')}/month`;
    }
    if (price >= 10000000) {
      return `₹${(price / 10000000).toFixed(2)} Cr`;
    }
    if (price >= 100000) {
      return `₹${(price / 100000).toFixed(2)} Lac`;
    }
    return `₹${price.toLocaleString('en-IN')}`;
  };

  return (
    <Card className="overflow-hidden hover:shadow-xl transition-all duration-300 group cursor-pointer">
      <div className="relative overflow-hidden" onClick={() => navigate(`/property/${property.id}`)}>
        <img
          src={property.images[0]}
          alt={property.title}
          className="w-full h-48 object-cover group-hover:scale-110 transition-transform duration-300"
        />
        {property.featured && (
          <Badge className="absolute top-2 left-2 bg-[#d82028] hover:bg-[#b81a22]">
            Featured
          </Badge>
        )}
        <button className="absolute top-2 right-2 bg-white p-2 rounded-full hover:bg-gray-100 transition-colors">
          <Heart size={18} className="text-gray-600" />
        </button>
        <Badge className="absolute bottom-2 left-2 bg-white text-gray-800">
          For {property.transactionType === 'sale' ? 'Sale' : 'Rent'}
        </Badge>
      </div>
      
      <CardContent className="p-4" onClick={() => navigate(`/property/${property.id}`)}>
        <div className="mb-2">
          <h3 className="font-bold text-lg text-gray-800 mb-1 line-clamp-1">
            {property.title}
          </h3>
          <div className="flex items-center text-gray-600 text-sm mb-2">
            <MapPin size={14} className="mr-1 text-[#d82028]" />
            <span className="line-clamp-1">{property.location}</span>
          </div>
        </div>

        <div className="flex items-center gap-3 text-sm text-gray-600 mb-3 pb-3 border-b">
          {property.bedrooms > 0 && (
            <div className="flex items-center gap-1">
              <Bed size={16} className="text-[#d82028]" />
              <span>{property.bedrooms} BHK</span>
            </div>
          )}
          {property.bathrooms > 0 && (
            <div className="flex items-center gap-1">
              <Bath size={16} className="text-[#d82028]" />
              <span>{property.bathrooms} Bath</span>
            </div>
          )}
          <div className="flex items-center gap-1">
            <Maximize2 size={16} className="text-[#d82028]" />
            <span>{property.area} {property.areaUnit}</span>
          </div>
        </div>

        <div className="flex items-center justify-between">
          <div>
            <p className="text-2xl font-bold text-[#d82028]">
              {formatPrice(property.price, property.transactionType)}
            </p>
            <p className="text-xs text-gray-500">Posted by {property.postedBy}</p>
          </div>
          <Button
            onClick={(e) => {
              e.stopPropagation();
              navigate(`/property/${property.id}`);
            }}
            size="sm"
            className="bg-[#d82028] hover:bg-[#b81a22]"
          >
            View Details
          </Button>
        </div>
      </CardContent>
    </Card>
  );
};

export default PropertyCard;
