import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Filter } from 'lucide-react';
import PropertyCard from '../components/PropertyCard';
import { Button } from '../components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../components/ui/select';
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from '../components/ui/sheet';
import { gujaratDistricts, propertyTypes, budgetRanges } from '../mockData';
import { propertyAPI } from '../utils/api';

const SearchPage = () => {
  const [searchParams] = useSearchParams();
  const [filteredProperties, setFilteredProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    type: searchParams.get('type') || '',
    district: searchParams.get('district') || '',
    propertyType: searchParams.get('propertyType') || '',
    budget: searchParams.get('budget') || '',
    bhk: searchParams.get('bhk') || '',
    furnishing: searchParams.get('furnishing') || ''
  });

  useEffect(() => {
    // Update filters from URL params
    setFilters({
      type: searchParams.get('type') || '',
      district: searchParams.get('district') || '',
      propertyType: searchParams.get('propertyType') || '',
      budget: searchParams.get('budget') || '',
      bhk: searchParams.get('bhk') || '',
      furnishing: searchParams.get('furnishing') || ''
    });
  }, [searchParams]);

  useEffect(() => {
    filterProperties();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filters]);

  const filterProperties = async () => {
    setLoading(true);
    try {
      // Build query params
      const params = {};
      if (filters.type && filters.type !== 'all') params.type = filters.type;
      if (filters.district && filters.district !== 'all') params.district = filters.district;
      if (filters.propertyType && filters.propertyType !== 'all') params.propertyType = filters.propertyType;
      if (filters.budget && filters.budget !== 'all') params.budget = filters.budget;
      if (filters.bhk && filters.bhk !== 'all') params.bhk = filters.bhk;
      if (filters.furnishing && filters.furnishing !== 'all') params.furnishing = filters.furnishing;

      // Fetch from API
      const response = await propertyAPI.getAll(params);
      setFilteredProperties(response.data.properties);
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        console.error('Error fetching properties:', error);
      }
      setFilteredProperties([]);
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (key, value) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  };

  const resetFilters = () => {
    setFilters({
      type: '',
      district: '',
      propertyType: '',
      budget: '',
      bhk: '',
      furnishing: ''
    });
  };

  const FilterPanel = () => (
    <div className="space-y-6">
      <div>
        <label className="text-sm font-medium mb-2 block">Transaction Type</label>
        <Select value={filters.type} onValueChange={(v) => handleFilterChange('type', v)}>
          <SelectTrigger>
            <SelectValue placeholder="All" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All</SelectItem>
            <SelectItem value="sale">Sale</SelectItem>
            <SelectItem value="rent">Rent</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div>
        <label className="text-sm font-medium mb-2 block">District</label>
        <Select value={filters.district} onValueChange={(v) => handleFilterChange('district', v)}>
          <SelectTrigger>
            <SelectValue placeholder="All Districts" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Districts</SelectItem>
            {gujaratDistricts.map(dist => (
              <SelectItem key={dist} value={dist}>{dist}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div>
        <label className="text-sm font-medium mb-2 block">Property Type</label>
        <Select value={filters.propertyType} onValueChange={(v) => handleFilterChange('propertyType', v)}>
          <SelectTrigger>
            <SelectValue placeholder="All Types" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Types</SelectItem>
            {propertyTypes.map(type => (
              <SelectItem key={type.id} value={type.id}>{type.name}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div>
        <label className="text-sm font-medium mb-2 block">Budget</label>
        <Select value={filters.budget} onValueChange={(v) => handleFilterChange('budget', v)}>
          <SelectTrigger>
            <SelectValue placeholder="Any Budget" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Any Budget</SelectItem>
            {budgetRanges.map((range) => (
              <SelectItem key={`${range.min}-${range.max}`} value={`${range.min}-${range.max}`}>{range.label}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div>
        <label className="text-sm font-medium mb-2 block">BHK</label>
        <Select value={filters.bhk} onValueChange={(v) => handleFilterChange('bhk', v)}>
          <SelectTrigger>
            <SelectValue placeholder="Any" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Any</SelectItem>
            <SelectItem value="1">1 BHK</SelectItem>
            <SelectItem value="2">2 BHK</SelectItem>
            <SelectItem value="3">3 BHK</SelectItem>
            <SelectItem value="4">4+ BHK</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <Button onClick={resetFilters} variant="outline" className="w-full">
        Reset Filters
      </Button>
    </div>
  );

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="container mx-auto px-4">
        <div className="mb-6">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">Search Properties</h1>
          <p className="text-gray-600">
            {filteredProperties.length} properties found
            {filters.district && ` in ${filters.district}`}
          </p>
        </div>

        <div className="flex gap-6">
          {/* Desktop Filter Sidebar */}
          <div className="hidden lg:block w-64 flex-shrink-0">
            <div className="bg-white rounded-lg p-6 sticky top-24">
              <h3 className="font-bold text-lg mb-4">Filters</h3>
              <FilterPanel />
            </div>
          </div>

          {/* Main Content */}
          <div className="flex-1">
            {/* Mobile Filter */}
            <div className="lg:hidden mb-4">
              <Sheet>
                <SheetTrigger asChild>
                  <Button variant="outline" className="w-full">
                    <Filter size={18} className="mr-2" />
                    Filters
                  </Button>
                </SheetTrigger>
                <SheetContent side="left">
                  <SheetHeader>
                    <SheetTitle>Filters</SheetTitle>
                  </SheetHeader>
                  <div className="mt-6">
                    <FilterPanel />
                  </div>
                </SheetContent>
              </Sheet>
            </div>

            {/* Properties Grid */}
            {loading ? (
              <div className="bg-white rounded-lg p-12 text-center">
                <p className="text-gray-500 text-lg">Loading properties...</p>
              </div>
            ) : filteredProperties.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {filteredProperties.map(property => (
                  <PropertyCard key={property.id} property={property} />
                ))}
              </div>
            ) : (
              <div className="bg-white rounded-lg p-12 text-center">
                <p className="text-gray-500 text-lg">No properties found matching your criteria</p>
                <Button onClick={resetFilters} className="mt-4 bg-[#d82028] hover:bg-[#b81a22]">
                  Reset Filters
                </Button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default SearchPage;