import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, MapPin, Home } from 'lucide-react';
import { Button } from './ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select';
import { Input } from './ui/input';
import { gujaratDistricts } from '../mockData';

const SearchBar = () => {
  const navigate = useNavigate();
  const [searchType, setSearchType] = useState('buy');
  const [district, setDistrict] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedPropertyTypes, setSelectedPropertyTypes] = useState([]);

  const propertyTypeOptions = [
    { id: 'apartment', label: 'Apartment' },
    { id: 'house', label: 'House' },
    { id: 'villa', label: 'Villa' },
    { id: 'plot', label: 'Plot' }
  ];

  const togglePropertyType = (typeId) => {
    if (selectedPropertyTypes.includes(typeId)) {
      setSelectedPropertyTypes(selectedPropertyTypes.filter(t => t !== typeId));
    } else {
      setSelectedPropertyTypes([...selectedPropertyTypes, typeId]);
    }
  };

  const handleSearch = () => {
    const params = new URLSearchParams();
    if (searchType) params.append('type', searchType);
    if (district) params.append('district', district);
    if (selectedPropertyTypes.length > 0) {
      params.append('propertyType', selectedPropertyTypes[0]);
    }
    
    navigate(`/search?${params.toString()}`);
  };

  return (
    <div className="bg-white rounded-lg shadow-lg p-8">
      {/* Transaction Type Tabs */}
      <div className="flex gap-3 mb-8">
        <button
          onClick={() => setSearchType('buy')}
          className={`flex items-center gap-2 px-8 py-3 rounded-md font-medium transition-all ${
            searchType === 'buy'
              ? 'bg-white shadow-md text-gray-800 border border-gray-200'
              : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
          }`}
        >
          <Home size={18} />
          Buy
        </button>
        <button
          onClick={() => setSearchType('rent')}
          className={`flex items-center gap-2 px-8 py-3 rounded-md font-medium transition-all ${
            searchType === 'rent'
              ? 'bg-white shadow-md text-gray-800 border border-gray-200'
              : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
          }`}
        >
          <Home size={18} />
          Rent
        </button>
        <button
          onClick={() => setSearchType('commercial')}
          className={`flex items-center gap-2 px-8 py-3 rounded-md font-medium transition-all ${
            searchType === 'commercial'
              ? 'bg-white shadow-md text-gray-800 border border-gray-200'
              : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
          }`}
        >
          <Home size={18} />
          Commercial
        </button>
        <button
          onClick={() => setSearchType('pg')}
          className={`flex items-center gap-2 px-8 py-3 rounded-md font-medium transition-all ${
            searchType === 'pg'
              ? 'bg-white shadow-md text-gray-800 border border-gray-200'
              : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
          }`}
        >
          <Home size={18} />
          PG
        </button>
      </div>

      {/* Search Inputs */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
        {/* District Dropdown */}
        <div>
          <Select value={district} onValueChange={setDistrict}>
            <SelectTrigger className="h-12 text-gray-600">
              <div className="flex items-center gap-2">
                <MapPin size={18} className="text-gray-400" />
                <SelectValue placeholder="Select City" />
              </div>
            </SelectTrigger>
            <SelectContent>
              {gujaratDistricts.map((dist) => (
                <SelectItem key={dist} value={dist}>
                  {dist}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Search Input */}
        <div className="relative">
          <Search className="absolute left-3 top-3.5 text-gray-400" size={18} />
          <Input
            type="text"
            placeholder="Search by locality, landmark or project"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10 h-12"
          />
        </div>
      </div>

      {/* Property Type Pills */}
      <div className="mb-6">
        <div className="flex items-center gap-3">
          <span className="text-gray-700 font-medium">Property Type:</span>
          <div className="flex gap-2 flex-wrap">
            {propertyTypeOptions.map((type) => (
              <button
                key={type.id}
                onClick={() => togglePropertyType(type.id)}
                className={`px-6 py-2 rounded-full border transition-all ${
                  selectedPropertyTypes.includes(type.id)
                    ? 'bg-gray-800 text-white border-gray-800'
                    : 'bg-white text-gray-700 border-gray-300 hover:border-gray-400'
                }`}
              >
                {type.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Search Button */}
      <Button
        onClick={handleSearch}
        className="w-full h-12 bg-[#d82028] hover:bg-[#b81a22] text-white text-base font-medium"
      >
        Search Properties
      </Button>
    </div>
  );
};

export default SearchBar;
