import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Menu, X, User, LogOut, Building2, Heart } from 'lucide-react';
import { Button } from './ui/button';
import MegaMenu from './MegaMenu';

const Header = ({ user, onLogout }) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [activeMenu, setActiveMenu] = useState(null);
  const navigate = useNavigate();

  const menuItems = [
    { id: 'buyer', label: 'For Buyer', path: '/search?type=buy' },
    { id: 'seller', label: 'For Seller', path: '/post-property' },
    { id: 'tenant', label: 'For Tenant', path: '/search?type=rent' },
    { id: 'dealer', label: 'For Dealer/Builder', path: '/dealer' },
    { id: 'loan', label: 'Loan Application', path: '/services' }
  ];

  return (
    <header className="bg-white shadow-md sticky top-0 z-50">
      {/* Top Bar */}
      <div className="bg-[#d82028] text-white py-2">
        <div className="container mx-auto px-4 flex justify-between items-center text-sm">
          <div className="flex items-center gap-4">
            <span>📞 +91 79 1234 5678</span>
            <span>✉️ info@propertysearch.com</span>
          </div>
          <div className="hidden md:block">
            <span>Gujarat's #1 Real Estate Portal</span>
          </div>
        </div>
      </div>

      {/* Main Navigation */}
      <div className="container mx-auto px-4">
        <div className="flex items-center justify-between py-4">
          {/* Logo */}
          <Link to="/" className="flex items-center gap-3">
            <div className="bg-[#d82028] text-white w-12 h-12 rounded flex items-center justify-center font-bold text-xl">
              PS
            </div>
            <div>
              <h1 className="text-xl font-bold text-gray-900">PropertySearch</h1>
              <p className="text-xs text-gray-600">Find Your Dream Property</p>
            </div>
          </Link>

          {/* Desktop Navigation */}
          <nav className="hidden lg:flex items-center gap-6">
            {menuItems.map((item) => (
              <div
                key={item.id}
                className="relative"
                onMouseEnter={() => setActiveMenu(item.id)}
                onMouseLeave={() => setActiveMenu(null)}
              >
                <Link
                  to={item.path}
                  className="text-gray-700 hover:text-[#d82028] font-medium transition-colors flex items-center gap-1"
                >
                  {item.label}
                  {(item.id === 'buyer' || item.id === 'seller' || item.id === 'tenant') && (
                    <span className="text-xs">▼</span>
                  )}
                </Link>
                {activeMenu === item.id && <MegaMenu menuType={item.id} />}
              </div>
            ))}
          </nav>

          {/* Right Side Icons & Buttons */}
          <div className="hidden lg:flex items-center gap-4">
            <button className="text-gray-700 hover:text-[#d82028]">
              <Heart size={22} />
            </button>
            {user ? (
              <div className="flex items-center gap-3">
                <Link to="/dashboard" className="flex items-center gap-1 text-gray-700 hover:text-[#d82028]">
                  <User size={18} />
                  <span className="text-sm">Login</span>
                </Link>
              </div>
            ) : (
              <Link to="/login" className="flex items-center gap-1 text-gray-700 hover:text-[#d82028]">
                <User size={18} />
                <span className="text-sm">Login</span>
              </Link>
            )}
            <Button
              onClick={() => navigate('/post-property')}
              className="bg-[#d82028] hover:bg-[#b81a22] text-white px-6"
            >
              Post Property
            </Button>
          </div>

          {/* Mobile Menu Toggle */}
          <button
            className="lg:hidden"
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          >
            {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>

        {/* Mobile Navigation */}
        {mobileMenuOpen && (
          <div className="lg:hidden pb-4 border-t">
            <nav className="flex flex-col gap-2 pt-4">
              {menuItems.map((item) => (
                <Link
                  key={item.id}
                  to={item.path}
                  className="py-2 text-gray-700 hover:text-[#d82028] hover:bg-gray-50 px-2 rounded"
                  onClick={() => setMobileMenuOpen(false)}
                >
                  {item.label}
                </Link>
              ))}
              <Button
                onClick={() => {
                  navigate('/post-property');
                  setMobileMenuOpen(false);
                }}
                className="bg-[#d82028] hover:bg-[#b81a22] text-white w-full mt-2"
              >
                Post Property
              </Button>
              {!user && (
                <div className="flex gap-2 mt-2">
                  <Button
                    onClick={() => {
                      navigate('/login');
                      setMobileMenuOpen(false);
                    }}
                    variant="outline"
                    className="flex-1"
                  >
                    Login
                  </Button>
                </div>
              )}
            </nav>
          </div>
        )}
      </div>
    </header>
  );
};

export default Header;
