import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { MapPin, Maximize2, Bed, Bath, ArrowLeft, Phone, Mail, Heart, Share2, IndianRupee } from 'lucide-react';
import { Button } from '../components/ui/button';
import { Card, CardContent } from '../components/ui/card';
import { Badge } from '../components/ui/badge';
import { toast } from '../hooks/use-toast';
import { propertyAPI } from '../utils/api';

const PropertyDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [property, setProperty] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedImage, setSelectedImage] = useState(0);

  useEffect(() => {
    fetchProperty();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const fetchProperty = async () => {
    try {
      const response = await propertyAPI.getById(id);
      setProperty(response.data.property);
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        console.error('Error fetching property:', error);
      }
      toast({
        title: "Error",
        description: "Failed to load property details",
        variant: "destructive"
      });
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <p className="text-xl text-gray-600">Loading property details...</p>
      </div>
    );
  }

  if (!property) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <h2 className="text-2xl font-bold mb-4">Property Not Found</h2>
          <Button onClick={() => navigate('/search')} className="bg-[#d82028] hover:bg-[#b81a22]">
            Back to Search
          </Button>
        </div>
      </div>
    );
  }

  const formatPrice = (price, type) => {
    if (type === 'rent') {
      return `₹${price.toLocaleString('en-IN')}/month`;
    }
    if (price >= 10000000) {
      return `₹${(price / 10000000).toFixed(2)} Crore`;
    }
    if (price >= 100000) {
      return `₹${(price / 100000).toFixed(2)} Lakh`;
    }
    return `₹${price.toLocaleString('en-IN')}`;
  };

  const handleContact = () => {
    toast({
      title: "Contact Information",
      description: "Please login to view contact details",
    });
  };

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="container mx-auto px-4">
        {/* Back Button */}
        <Button
          onClick={() => navigate(-1)}
          variant="ghost"
          className="mb-4"
        >
          <ArrowLeft size={18} className="mr-2" />
          Back
        </Button>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-6">
            {/* Image Gallery */}
            <Card>
              <CardContent className="p-0">
                <div className="relative">
                  <img
                    src={property.images[selectedImage]}
                    alt={property.title}
                    className="w-full h-96 object-cover rounded-t-lg"
                  />
                  {property.featured && (
                    <Badge className="absolute top-4 left-4 bg-[#d82028]">
                      Featured
                    </Badge>
                  )}
                  <div className="absolute top-4 right-4 flex gap-2">
                    <Button size="icon" variant="secondary">
                      <Heart size={20} />
                    </Button>
                    <Button size="icon" variant="secondary">
                      <Share2 size={20} />
                    </Button>
                  </div>
                </div>
                {property.images.length > 1 && (
                  <div className="flex gap-2 p-4">
                    {property.images.map((img, idx) => (
                      <img
                        key={`${property.id}-img-${idx}`}
                        src={img}
                        alt={`View ${idx + 1}`}
                        onClick={() => setSelectedImage(idx)}
                        className={`w-20 h-20 object-cover rounded cursor-pointer border-2 ${
                          selectedImage === idx ? 'border-[#d82028]' : 'border-transparent'
                        }`}
                      />
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>

            {/* Property Details */}
            <Card>
              <CardContent className="p-6">
                <div className="flex items-start justify-between mb-4">
                  <div>
                    <h1 className="text-3xl font-bold text-gray-900 mb-2">{property.title}</h1>
                    <div className="flex items-center text-gray-600 mb-2">
                      <MapPin size={18} className="mr-2 text-[#d82028]" />
                      <span>{property.location}</span>
                    </div>
                    <Badge variant="secondary">
                      For {property.transactionType === 'sale' ? 'Sale' : 'Rent'}
                    </Badge>
                  </div>
                  <div className="text-right">
                    <p className="text-3xl font-bold text-[#d82028]">
                      {formatPrice(property.price, property.transactionType)}
                    </p>
                  </div>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 py-6 border-y">
                  {property.bedrooms > 0 && (
                    <div className="text-center">
                      <Bed className="w-8 h-8 mx-auto mb-2 text-[#d82028]" />
                      <p className="font-semibold">{property.bedrooms} BHK</p>
                      <p className="text-sm text-gray-600">Bedrooms</p>
                    </div>
                  )}
                  {property.bathrooms > 0 && (
                    <div className="text-center">
                      <Bath className="w-8 h-8 mx-auto mb-2 text-[#d82028]" />
                      <p className="font-semibold">{property.bathrooms}</p>
                      <p className="text-sm text-gray-600">Bathrooms</p>
                    </div>
                  )}
                  <div className="text-center">
                    <Maximize2 className="w-8 h-8 mx-auto mb-2 text-[#d82028]" />
                    <p className="font-semibold">{property.area} {property.areaUnit}</p>
                    <p className="text-sm text-gray-600">Area</p>
                  </div>
                  {property.furnishingStatus !== 'NA' && (
                    <div className="text-center">
                      <div className="w-8 h-8 mx-auto mb-2 flex items-center justify-center">
                        <IndianRupee className="text-[#d82028]" />
                      </div>
                      <p className="font-semibold">{property.furnishingStatus}</p>
                      <p className="text-sm text-gray-600">Furnishing</p>
                    </div>
                  )}
                </div>

                <div className="mt-6">
                  <h3 className="font-bold text-lg mb-3">Description</h3>
                  <p className="text-gray-700 leading-relaxed">{property.description}</p>
                </div>

                <div className="mt-6 grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-sm text-gray-600">Property Type</p>
                    <p className="font-semibold capitalize">{property.propertyType}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-600">Posted By</p>
                    <p className="font-semibold">{property.postedBy}</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Map Placeholder */}
            <Card>
              <CardContent className="p-6">
                <h3 className="font-bold text-lg mb-4">Location</h3>
                <div className="bg-gray-200 h-64 rounded-lg flex items-center justify-center">
                  <p className="text-gray-500">Map will be integrated here</p>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Contact Card */}
            <Card className="sticky top-24">
              <CardContent className="p-6">
                <h3 className="font-bold text-lg mb-4">Contact {property.postedBy}</h3>
                <div className="space-y-3">
                  <Button onClick={handleContact} className="w-full bg-[#d82028] hover:bg-[#b81a22]">
                    <Phone size={18} className="mr-2" />
                    Call Now
                  </Button>
                  <Button onClick={handleContact} variant="outline" className="w-full">
                    <Mail size={18} className="mr-2" />
                    Send Message
                  </Button>
                </div>
                <p className="text-xs text-gray-500 mt-4 text-center">
                  Login to view contact details
                </p>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PropertyDetails;