import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Building2, TrendingUp, Shield, Users, ArrowRight, Award, CheckCircle } from 'lucide-react';
import SearchBar from '../components/SearchBar';
import PropertyCard from '../components/PropertyCard';
import { Button } from '../components/ui/button';
import { Card, CardContent } from '../components/ui/card';
import { testimonials, gujaratDistricts } from '../mockData';
import { propertyAPI } from '../utils/api';

const HomePage = () => {
  const navigate = useNavigate();
  const [featuredProperties, setFeaturedProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const popularCities = gujaratDistricts.slice(0, 8);

  useEffect(() => {
    fetchFeaturedProperties();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const fetchFeaturedProperties = async () => {
    try {
      const response = await propertyAPI.getAll();
      const allProperties = response.data.properties;
      // Filter featured properties
      const featured = allProperties.filter(p => p.featured);
      setFeaturedProperties(featured.slice(0, 3));
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        console.error('Error fetching properties:', error);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen">
      {/* Hero Section */}
      <section className="relative bg-gradient-to-br from-gray-50 to-gray-100 py-20 md:py-28">
        <div className="container mx-auto px-4">
          <div className="max-w-4xl mx-auto text-center mb-12">
            <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold text-gray-900 mb-4">
              Find Your Perfect Property in Gujarat
            </h1>
            <p className="text-lg md:text-xl text-gray-600">
              Discover 15,000+ verified properties across all major cities
            </p>
          </div>
          
          <div className="max-w-4xl mx-auto">
            <SearchBar />
          </div>

          {/* Quick Stats */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-6 max-w-4xl mx-auto mt-16">
            <div className="bg-white rounded-lg p-6 text-center shadow-md">
              <p className="text-4xl font-bold text-[#d82028] mb-1">15,000+</p>
              <p className="text-sm text-gray-600">Properties</p>
            </div>
            <div className="bg-white rounded-lg p-6 text-center shadow-md">
              <p className="text-4xl font-bold text-[#d82028] mb-1">20+</p>
              <p className="text-sm text-gray-600">Cities</p>
            </div>
            <div className="bg-white rounded-lg p-6 text-center shadow-md">
              <p className="text-4xl font-bold text-[#d82028] mb-1">5,000+</p>
              <p className="text-sm text-gray-600">Happy Customers</p>
            </div>
            <div className="bg-white rounded-lg p-6 text-center shadow-md">
              <p className="text-4xl font-bold text-[#d82028] mb-1">500+</p>
              <p className="text-sm text-gray-600">Dealers</p>
            </div>
          </div>
        </div>
      </section>

      {/* Featured Properties */}
      <section className="py-16 bg-white">
        <div className="container mx-auto px-4">
          <div className="flex justify-between items-center mb-8">
            <div>
              <h2 className="text-3xl font-bold text-gray-900 mb-2">Featured Properties</h2>
              <p className="text-gray-600">Handpicked properties for you</p>
            </div>
            <Button
              onClick={() => navigate('/search')}
              variant="outline"
              className="border-[#d82028] text-[#d82028] hover:bg-[#d82028] hover:text-white"
            >
              View All
              <ArrowRight size={18} className="ml-2" />
            </Button>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {loading ? (
              <p className="col-span-full text-center text-gray-500">Loading properties...</p>
            ) : featuredProperties.length > 0 ? (
              featuredProperties.map((property) => (
                <PropertyCard key={property.id} property={property} />
              ))
            ) : (
              <p className="col-span-full text-center text-gray-500">No featured properties available</p>
            )}
          </div>
        </div>
      </section>

      {/* Popular Cities */}
      <section className="py-16 bg-gray-50">
        <div className="container mx-auto px-4">
          <div className="text-center mb-12">
            <h2 className="text-3xl font-bold text-gray-900 mb-2">Explore Properties by City</h2>
            <p className="text-gray-600">Find your perfect property in Gujarat's top cities</p>
          </div>
          
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {popularCities.map((city) => (
              <Card
                key={city}
                className="hover:shadow-lg transition-all cursor-pointer group"
                onClick={() => navigate(`/search?district=${city}`)}
              >
                <CardContent className="p-6 text-center">
                  <Building2 className="w-12 h-12 mx-auto mb-3 text-[#d82028] group-hover:scale-110 transition-transform" />
                  <h3 className="font-bold text-lg text-gray-800">{city}</h3>
                  <p className="text-sm text-gray-600 mt-1">View Properties</p>
                </CardContent>
              </Card>
            ))}
          </div>
        </div>
      </section>

      {/* Why Choose Us */}
      <section className="py-16 bg-white">
        <div className="container mx-auto px-4">
          <div className="text-center mb-12">
            <h2 className="text-3xl font-bold text-gray-900 mb-2">Why Choose PropertySearch?</h2>
            <p className="text-gray-600">Your trusted partner in real estate</p>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <Card className="text-center p-6 hover:shadow-lg transition-shadow">
              <div className="bg-red-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                <Shield className="text-[#d82028] w-8 h-8" />
              </div>
              <h3 className="font-bold text-lg mb-2">Verified Properties</h3>
              <p className="text-sm text-gray-600">All properties are verified and authenticated</p>
            </Card>
            
            <Card className="text-center p-6 hover:shadow-lg transition-shadow">
              <div className="bg-red-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                <Users className="text-[#d82028] w-8 h-8" />
              </div>
              <h3 className="font-bold text-lg mb-2">Expert Guidance</h3>
              <p className="text-sm text-gray-600">Professional support throughout your journey</p>
            </Card>
            
            <Card className="text-center p-6 hover:shadow-lg transition-shadow">
              <div className="bg-red-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                <TrendingUp className="text-[#d82028] w-8 h-8" />
              </div>
              <h3 className="font-bold text-lg mb-2">Best Prices</h3>
              <p className="text-sm text-gray-600">Competitive pricing with no hidden charges</p>
            </Card>
            
            <Card className="text-center p-6 hover:shadow-lg transition-shadow">
              <div className="bg-red-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                <Award className="text-[#d82028] w-8 h-8" />
              </div>
              <h3 className="font-bold text-lg mb-2">Trusted Platform</h3>
              <p className="text-sm text-gray-600">5000+ satisfied customers across Gujarat</p>
            </Card>
          </div>
        </div>
      </section>

      {/* Services */}
      <section className="py-16 bg-gradient-to-br from-gray-50 to-red-50">
        <div className="container mx-auto px-4">
          <div className="text-center mb-12">
            <h2 className="text-3xl font-bold text-gray-900 mb-2">Our Services</h2>
            <p className="text-gray-600">Complete real estate solutions under one roof</p>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl mx-auto">
            <Card className="hover:shadow-xl transition-shadow">
              <CardContent className="p-6">
                <CheckCircle className="text-[#d82028] w-12 h-12 mb-4" />
                <h3 className="font-bold text-xl mb-3">Home Loan Assistance</h3>
                <p className="text-gray-600 mb-4">Get the best home loan deals with our partner banks. Easy process and quick approval.</p>
                <Button
                  onClick={() => navigate('/services/loan')}
                  variant="link"
                  className="text-[#d82028] p-0"
                >
                  Learn More <ArrowRight size={16} className="ml-1" />
                </Button>
              </CardContent>
            </Card>
            
            <Card className="hover:shadow-xl transition-shadow">
              <CardContent className="p-6">
                <CheckCircle className="text-[#d82028] w-12 h-12 mb-4" />
                <h3 className="font-bold text-xl mb-3">Legal Services</h3>
                <p className="text-gray-600 mb-4">Expert legal assistance for property documentation and registration.</p>
                <Button
                  onClick={() => navigate('/services/legal')}
                  variant="link"
                  className="text-[#d82028] p-0"
                >
                  Learn More <ArrowRight size={16} className="ml-1" />
                </Button>
              </CardContent>
            </Card>
            
            <Card className="hover:shadow-xl transition-shadow">
              <CardContent className="p-6">
                <CheckCircle className="text-[#d82028] w-12 h-12 mb-4" />
                <h3 className="font-bold text-xl mb-3">Property Valuation</h3>
                <p className="text-gray-600 mb-4">Professional property valuation services for accurate market prices.</p>
                <Button
                  onClick={() => navigate('/services/valuation')}
                  variant="link"
                  className="text-[#d82028] p-0"
                >
                  Learn More <ArrowRight size={16} className="ml-1" />
                </Button>
              </CardContent>
            </Card>
          </div>
        </div>
      </section>

      {/* Testimonials */}
      <section className="py-16 bg-white">
        <div className="container mx-auto px-4">
          <div className="text-center mb-12">
            <h2 className="text-3xl font-bold text-gray-900 mb-2">What Our Customers Say</h2>
            <p className="text-gray-600">Real experiences from real people</p>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl mx-auto">
            {testimonials.map((testimonial) => (
              <Card key={testimonial.id} className="hover:shadow-lg transition-shadow">
                <CardContent className="p-6">
                  <div className="flex items-center gap-3 mb-4">
                    <img
                      src={testimonial.avatar}
                      alt={testimonial.name}
                      className="w-12 h-12 rounded-full"
                    />
                    <div>
                      <h4 className="font-bold text-gray-800">{testimonial.name}</h4>
                      <p className="text-sm text-gray-600">{testimonial.location}</p>
                    </div>
                  </div>
                  <div className="flex gap-1 mb-3">
                    {[...Array(testimonial.rating)].map((_, i) => (
                      <span key={`star-${testimonial.id}-${i}`} className="text-yellow-400">★</span>
                    ))}
                  </div>
                  <p className="text-gray-700 italic">"{testimonial.comment}"</p>
                </CardContent>
              </Card>
            ))}
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section className="py-16 bg-gradient-to-r from-[#d82028] to-[#b81a22] text-white">
        <div className="container mx-auto px-4 text-center">
          <h2 className="text-3xl md:text-4xl font-bold mb-4">Ready to Find Your Dream Property?</h2>
          <p className="text-lg mb-8 opacity-90">Join thousands of satisfied customers across Gujarat</p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <Button
              onClick={() => navigate('/search')}
              size="lg"
              className="bg-white text-[#d82028] hover:bg-gray-100"
            >
              Search Properties
            </Button>
            <Button
              onClick={() => navigate('/post-property')}
              size="lg"
              variant="outline"
              className="border-white text-white hover:bg-white hover:text-[#d82028]"
            >
              Post Your Property
            </Button>
          </div>
        </div>
      </section>
    </div>
  );
};

export default HomePage;
