import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Upload, MapPin, Home, IndianRupee } from 'lucide-react';
import { Button } from '../components/ui/button';
import { Input } from '../components/ui/input';
import { Textarea } from '../components/ui/textarea';
import { Card, CardContent, CardHeader, CardTitle } from '../components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../components/ui/select';
import { toast } from '../hooks/use-toast';
import { gujaratDistricts, propertyTypes } from '../mockData';
import { propertyAPI, uploadAPI } from '../utils/api';

const PostPropertyPage = () => {
  const navigate = useNavigate();
  const [uploading, setUploading] = useState(false);
  const [selectedFiles, setSelectedFiles] = useState([]);
  const [formData, setFormData] = useState({
    title: '',
    propertyType: '',
    transactionType: 'sale',
    price: '',
    location: '',
    district: '',
    area: '',
    areaUnit: 'sqft',
    bedrooms: '',
    bathrooms: '',
    furnishingStatus: 'Unfurnished',
    description: '',
    images: []
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    const user = localStorage.getItem('user');
    if (!user) {
      toast({
        title: "Login Required",
        description: "Please login to post a property",
        variant: "destructive"
      });
      navigate('/login');
      return;
    }

    try {
      setUploading(true);
      
      // Upload images first if any
      let imagePaths = [];
      if (selectedFiles.length > 0) {
        const uploadResponse = await uploadAPI.uploadImages(selectedFiles);
        imagePaths = uploadResponse.data.filePaths;
      }
      
      // Create property
      await propertyAPI.create({
        title: formData.title,
        propertyType: formData.propertyType,
        transactionType: formData.transactionType,
        price: parseFloat(formData.price),
        location: formData.location,
        district: formData.district,
        area: parseFloat(formData.area),
        areaUnit: formData.areaUnit,
        bedrooms: parseInt(formData.bedrooms) || 0,
        bathrooms: parseInt(formData.bathrooms) || 0,
        furnishingStatus: formData.furnishingStatus,
        description: formData.description,
        images: imagePaths
      });
      
      toast({
        title: "Property Submitted!",
        description: "Your property will be published after admin approval within 24 hours",
      });
      
      navigate('/');
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        console.error('Error creating property:', error);
      }
      toast({
        title: "Submission Failed",
        description: error.response?.data?.detail || "Please try again",
        variant: "destructive"
      });
    } finally {
      setUploading(false);
    }
  };

  const handleImageUpload = (e) => {
    const files = Array.from(e.target.files);
    if (files.length > 10) {
      toast({
        title: "Too many images",
        description: "Maximum 10 images allowed",
        variant: "destructive"
      });
      return;
    }
    setSelectedFiles(files);
    toast({
      title: "Images Selected",
      description: `${files.length} image(s) selected`,
    });
  };

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="container mx-auto px-4 max-w-3xl">
        <Card>
          <CardHeader>
            <CardTitle className="text-2xl">Post Your Property</CardTitle>
            <p className="text-gray-600 text-sm mt-2">Fill in the details to list your property</p>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Basic Information */}
              <div className="space-y-4">
                <h3 className="font-bold text-lg">Basic Information</h3>
                
                <div>
                  <label className="text-sm font-medium mb-2 block">Property Title *</label>
                  <Input
                    placeholder="e.g., 3 BHK Apartment for Sale"
                    value={formData.title}
                    onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                    required
                  />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="text-sm font-medium mb-2 block">Property Type *</label>
                    <Select value={formData.propertyType} onValueChange={(v) => setFormData({ ...formData, propertyType: v })} required>
                      <SelectTrigger>
                        <SelectValue placeholder="Select type" />
                      </SelectTrigger>
                      <SelectContent>
                        {propertyTypes.map(type => (
                          <SelectItem key={type.id} value={type.id}>{type.name}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div>
                    <label className="text-sm font-medium mb-2 block">Transaction Type *</label>
                    <Select value={formData.transactionType} onValueChange={(v) => setFormData({ ...formData, transactionType: v })}>
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="sale">For Sale</SelectItem>
                        <SelectItem value="rent">For Rent</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>
              </div>

              {/* Location */}
              <div className="space-y-4">
                <h3 className="font-bold text-lg">Location</h3>
                
                <div>
                  <label className="text-sm font-medium mb-2 block">District *</label>
                  <Select value={formData.district} onValueChange={(v) => setFormData({ ...formData, district: v })} required>
                    <SelectTrigger>
                      <SelectValue placeholder="Select district" />
                    </SelectTrigger>
                    <SelectContent>
                      {gujaratDistricts.map(dist => (
                        <SelectItem key={dist} value={dist}>{dist}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <label className="text-sm font-medium mb-2 block">Locality/Area *</label>
                  <Input
                    placeholder="e.g., Bodakdev, Satellite"
                    value={formData.location}
                    onChange={(e) => setFormData({ ...formData, location: e.target.value })}
                    required
                  />
                </div>
              </div>

              {/* Property Details */}
              <div className="space-y-4">
                <h3 className="font-bold text-lg">Property Details</h3>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="text-sm font-medium mb-2 block">Built-up Area *</label>
                    <div className="flex gap-2">
                      <Input
                        type="number"
                        placeholder="Area"
                        value={formData.area}
                        onChange={(e) => setFormData({ ...formData, area: e.target.value })}
                        required
                      />
                      <Select value={formData.areaUnit} onValueChange={(v) => setFormData({ ...formData, areaUnit: v })}>
                        <SelectTrigger className="w-32">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="sqft">Sq.ft</SelectItem>
                          <SelectItem value="sqyd">Sq.yd</SelectItem>
                          <SelectItem value="sqm">Sq.m</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                  </div>

                  <div>
                    <label className="text-sm font-medium mb-2 block">Price *</label>
                    <Input
                      type="number"
                      placeholder={formData.transactionType === 'rent' ? 'Monthly rent' : 'Total price'}
                      value={formData.price}
                      onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                      required
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div>
                    <label className="text-sm font-medium mb-2 block">Bedrooms</label>
                    <Input
                      type="number"
                      placeholder="0"
                      value={formData.bedrooms}
                      onChange={(e) => setFormData({ ...formData, bedrooms: e.target.value })}
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium mb-2 block">Bathrooms</label>
                    <Input
                      type="number"
                      placeholder="0"
                      value={formData.bathrooms}
                      onChange={(e) => setFormData({ ...formData, bathrooms: e.target.value })}
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium mb-2 block">Furnishing</label>
                    <Select value={formData.furnishingStatus} onValueChange={(v) => setFormData({ ...formData, furnishingStatus: v })}>
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="Fully-Furnished">Fully Furnished</SelectItem>
                        <SelectItem value="Semi-Furnished">Semi Furnished</SelectItem>
                        <SelectItem value="Unfurnished">Unfurnished</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>
              </div>

              {/* Description */}
              <div>
                <label className="text-sm font-medium mb-2 block">Description *</label>
                <Textarea
                  placeholder="Describe your property in detail..."
                  rows={5}
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  required
                />
              </div>

              {/* Images */}
              <div>
                <label className="text-sm font-medium mb-2 block">Property Images *</label>
                <div className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center">
                  <Upload className="w-12 h-12 mx-auto mb-4 text-gray-400" />
                  <p className="text-gray-600 mb-2">Upload property images</p>
                  <Input
                    type="file"
                    accept="image/*"
                    multiple
                    onChange={handleImageUpload}
                    className="max-w-xs mx-auto"
                  />
                  <p className="text-xs text-gray-500 mt-2">Upload up to 10 images (JPG, PNG)</p>
                </div>
              </div>

              {/* Submit */}
              <div className="flex gap-4">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => navigate(-1)}
                  className="flex-1"
                  disabled={uploading}
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  className="flex-1 bg-[#d82028] hover:bg-[#b81a22]"
                  disabled={uploading}
                >
                  {uploading ? 'Submitting...' : 'Submit for Approval'}
                </Button>
              </div>

              <p className="text-xs text-gray-500 text-center">
                * Your property will be reviewed and published within 24 hours after admin approval
              </p>
            </form>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default PostPropertyPage;
